<?php
declare(strict_types=1);
function runBulkScoreCases(PDO $db,callable $q,callable $reset,callable $pair,callable $hash,array $users):void
{
    $score=new BulkExactMatchService($db,BulkExactMatchService::SCORE);$exact=new BulkExactMatchService($db);
    $confirm=fn(array $p,?string $op=null)=>$score->confirm($users['admin'],$op??bin2hex(random_bytes(16)),$p['digest']);
    foreach(['0.4999'=>0,'0.5000'=>0,'0.5001'=>1,'0.5049'=>1,'0.5100'=>1,'0.9900'=>1] as $value=>$expected){$reset();$x=$pair([],['signer']);$q('UPDATE identity_match_candidates SET match_score=?',[$value]);$before=$hash();$p=$score->preview($users['admin']);bulkCheck($p['summary']['score_above_half']===$expected&&$p['summary']['eligible_candidates']===$expected,'stored DECIMAL threshold '.$value.' compared strictly, without display rounding');bulkCheck($before===$hash(),'score preview is read-only at '.$value);}
    $reset();$x=$pair(['payer_email'=>null,'waiver_email'=>null],['signer']);$q('UPDATE identity_match_candidates SET match_score=0.5200');$p=$score->preview($users['admin']);bulkCheck($p['summary']['eligible_candidates']===1&&$exact->preview($users['admin'])['summary']['eligible_candidates']===0,'score-qualified isolated signer may qualify without email while exact policy remains unchanged');$confirm($p);bulkCheck((int)$q('SELECT COUNT(*) FROM people')->fetchColumn()===1&&(int)$q('SELECT COUNT(*) FROM members')->fetchColumn()===0,'signer-only score confirmation never creates membership');
    $reset();$x=$pair(['payer_email'=>null,'waiver_email'=>null]);$q('UPDATE identity_match_candidates SET match_score=0.5200');$p=$score->preview($users['admin']);$op=bin2hex(random_bytes(16));bulkCheck($p['summary']['eligible_candidates']===2&&$p['summary']['members_to_create']===0,'native adult Self roles qualify independently from missing email');$confirm($p,$op);bulkCheck((int)$q('SELECT COUNT(*) FROM people')->fetchColumn()===1&&(int)$q('SELECT COUNT(*) FROM members')->fetchColumn()===0,'self-payer student uses one person; membership needs separate evidence');
    $events=$q("SELECT metadata FROM audit_log WHERE action='identity_confirmed'")->fetchAll(PDO::FETCH_COLUMN);bulkCheck(count($events)===3&&count(array_filter($events,fn($j)=>(json_decode($j,true)['bulk_operation']['operation_id']??null)===$op))===3,'each association audit carries authenticated bulk operation provenance');
    $before=$hash();$again=$confirm($p,$op);bulkCheck($again['replayed']&&$before===$hash(),'score policy receipt replay is idempotent');bulkThrows(fn()=>$exact->confirm($users['admin'],$op,$p['digest']),'INVALID_BULK_PREVIEW','receipt cannot be reused across confirmation policies');
    $reset();$x=$pair();$q('UPDATE identity_match_candidates SET match_score=0.5000 WHERE id=?',[$x['ids']['signer']]);$p=$score->preview($users['admin']);bulkCheck($p['summary']['score_above_half']===1&&$p['summary']['eligible_candidates']===0,'student score cannot indirectly confirm a signer exactly at the threshold');
    $reset();$x=$pair([],['source_name_unresolved']);$p=$score->preview($users['admin']);bulkCheck($p['summary']['eligible_candidates']===0&&isset($p['exclusions']['self_signer_not_score_qualified']),'missing persisted signer evaluation is not replaced by an invented score');
    $person=(new People($db))->create('John','Smith');(new IdentityAssociations($db))->decide('cognito','waiver',$x['locator'],'signer',(int)$person['id'],'confirmed',$users['admin']);$p=$score->preview($users['admin']);bulkCheck($p['summary']['eligible_candidates']===1&&$p['summary']['people_to_reuse']===1,'existing manually confirmed signer satisfies the Self role protection without rescoring');$confirm($p);
    $reset();$x=$pair(['payer'=>'Jane Smith','signer'=>'Jane Smith','student'=>'Johnny Smith','relationship'=>'Mother','payer_email'=>'family@example.invalid','waiver_email'=>'family@example.invalid','dob'=>'2015-01-01']);$p=$score->preview($users['admin']);bulkCheck($p['summary']['score_above_half']===2&&$p['summary']['eligible_candidates']===1&&$p['summary']['score_qualified_excluded']===1&&$p['review_groups'][0]['reason']==='student_role_separation','parent/student candidate remains a separate review group despite score');$confirm($p);bulkCheck($q('SELECT student_person_id FROM cognito_waivers')->fetchColumn()===null&&(int)$q('SELECT COUNT(*) FROM members')->fetchColumn()===0&&(int)$q('SELECT COUNT(*) FROM person_relationships')->fetchColumn()===0,'parent signer approval never merges child or infers household relationships');
    $reset();$pair(['format'=>'legacy','name_role'=>'unresolved']);$p=$score->preview($users['admin']);bulkCheck($p['summary']['eligible_candidates']===1&&in_array('legacy_source_role_ambiguous',array_column($p['review_groups'],'reason'),true),'high-scoring legacy student source-name ambiguity remains protected');
    $reset();$a=$pair();$b=$pair();$p=$score->preview($users['admin']);bulkCheck($p['summary']['eligible_candidates']===4&&$p['summary']['people_to_create']===1&&$p['summary']['members_to_create']===0,'repeated waivers and exact duplicate payer accounts share one safe group');$confirm($p);bulkCheck((int)$q('SELECT COUNT(*) FROM stripe_customers')->fetchColumn()===2&&(int)$q('SELECT COUNT(*) FROM cognito_waivers')->fetchColumn()===2&&(int)$q('SELECT COUNT(*) FROM people')->fetchColumn()===1,'score confirmation preserves all external account/waiver records');
    $reset();$a=$pair(['payer_email'=>null,'waiver_email'=>null]);$b=$pair(['payer_email'=>null,'waiver_email'=>null]);$q('UPDATE identity_match_candidates SET stripe_customer_id=? WHERE stripe_customer_id=?',[$a['cid'],$b['cid']]);$q('DELETE FROM stripe_customers WHERE id=?',[$b['cid']]);$q('UPDATE identity_match_candidates SET match_score=0.5200');$p=$score->preview($users['admin']);bulkCheck($p['summary']['people_to_create']===1&&$p['summary']['eligible_candidates']===4,'one payer anchors repeated compatible waivers without email-only grouping');
    $reset();$pair(['payer_email'=>null,'waiver_email'=>null]);$pair(['payer_email'=>null,'waiver_email'=>null]);$q('UPDATE identity_match_candidates SET match_score=0.5200');bulkCheck($score->preview($users['admin'])['summary']['eligible_candidates']===0,'isolated name-only components cannot duplicate one unknown identity');
    $reset();$a=$pair([],['signer']);$b=$pair(['payer_email'=>'alternate@example.invalid','waiver_email'=>'alternate@example.invalid'],['signer']);$q('UPDATE identity_match_candidates SET cognito_waiver_id=? WHERE id=?',[$a['wid'],$b['ids']['signer']]);$p=$score->preview($users['admin']);bulkCheck($p['summary']['eligible_candidates']===0&&isset($p['exclusions']['competing_payer_proposals']),'multiple payer proposals for one signer without verified equivalence are excluded');
    $reset();$a=$pair(['payer'=>'Jane Smith','signer'=>'Jane Smith','student'=>'Jane Smith','payer_email'=>'family@example.invalid','waiver_email'=>'family@example.invalid'],['signer']);$b=$pair(['payer'=>'Johnny Smith','signer'=>'Johnny Smith','student'=>'Johnny Smith','payer_email'=>'family@example.invalid','waiver_email'=>'family@example.invalid'],['signer']);$p=$score->preview($users['admin']);bulkCheck($p['summary']['people_to_create']===2,'household email with different names never connects otherwise independent identities');
    $q("INSERT INTO identity_match_candidates(stripe_customer_id,cognito_waiver_id,waiver_role,match_score,match_method,match_reason,match_status,evidence,hard_conflict) VALUES (?,?,'signer',0.9900,'shared_email','review_signals','possible',?,0)",[$a['cid'],$b['wid'],json_encode(['signals'=>['exact_email'],'conflicts'=>['different_full_name']])]);$p=$score->preview($users['admin']);bulkCheck($p['summary']['eligible_candidates']===0&&isset($p['exclusions']['competing_source_names']),'transitive conflicting household bridge quarantines the component rather than selecting a high score');
    $reset();$a=$pair(['payer_email'=>null,'waiver_email'=>null,'dob'=>'1980-01-01'],['signer']);$b=$pair(['payer_email'=>null,'waiver_email'=>null,'dob'=>'1990-01-01'],['signer']);$q('UPDATE identity_match_candidates SET stripe_customer_id=? WHERE id=?',[$a['cid'],$b['ids']['signer']]);$q('DELETE FROM stripe_customers WHERE id=?',[$b['cid']]);$q('UPDATE identity_match_candidates SET match_score=0.5200');bulkCheck($score->preview($users['admin'])['summary']['eligible_candidates']===0,'contradictory native Self DOB evidence blocks repeated signer-only proposals');
    $reset();$pair(['dob'=>'2015-01-01']);bulkCheck($score->preview($users['admin'])['summary']['eligible_candidates']===0,'known minor Self evidence cannot create an adult member despite high scores');
    $reset();$pair(['signer'=>null]);bulkCheck($score->preview($users['admin'])['summary']['eligible_candidates']===0,'missing signer identity cannot be approved by a high persisted score alone');
    foreach(['reject','later'] as $decision){$reset();$x=$pair();(new MatchReviewService($db))->decide($x['ids']['signer'],$decision,$users['admin'],[]);bulkCheck($score->preview($users['admin'])['summary']['eligible_candidates']===0,'score policy preserves manual '.$decision.' precedence');}
    $reset();$x=$pair();$q('UPDATE identity_match_candidates SET hard_conflict=1,evidence=? WHERE id=?',[json_encode(['signals'=>['exact_email'],'conflicts'=>['conflicting_birth_date']]),$x['ids']['source_name_unresolved']]);bulkCheck($score->preview($users['admin'])['summary']['eligible_candidates']===0,'high score never overrides hard DOB conflict');
    $reset();$x=$pair();$one=(new People($db))->create('John','Smith');$two=(new People($db))->create('John','Smith');$identity=new IdentityAssociations($db);$identity->decide('stripe','customer',$x['external'],'customer',(int)$one['id'],'confirmed',$users['admin']);$identity->decide('cognito','waiver',$x['locator'],'signer',(int)$two['id'],'confirmed',$users['admin']);bulkCheck($score->preview($users['admin'])['summary']['eligible_candidates']===0,'existing contradictory accepted people cannot be score-merged');
    $reset();$a=$pair(['payer_email'=>'old@example.invalid','waiver_email'=>'old@example.invalid']);$b=$pair(['payer_email'=>'new@example.invalid','waiver_email'=>'new@example.invalid']);$person=(new People($db))->create('John','Smith');$identity=new IdentityAssociations($db);foreach([$a,$b] as $x){$identity->decide('stripe','customer',$x['external'],'customer',(int)$person['id'],'confirmed',$users['admin']);$identity->decide('cognito','waiver',$x['locator'],'signer',(int)$person['id'],'confirmed',$users['admin']);}$p=$score->preview($users['admin']);bulkCheck($p['summary']['people_to_reuse']===1&&$p['summary']['members_to_create']===0,'accepted person identity spans email groups without duplicate people/members');$confirm($p);
    $reset();$x=$pair();$p=$score->preview($users['admin']);$q('UPDATE identity_match_candidates SET match_score=0.5000 WHERE id=?',[$x['ids']['signer']]);$before=$hash();bulkThrows(fn()=>$confirm($p),'BULK_PREVIEW_STALE','score change at threshold after preview invalidates complete operation');bulkCheck($before===$hash(),'stale score confirmation makes no partial changes');
    $reset();$pair();$p=$score->preview($users['admin']);$before=$hash();$db->arm(2);bulkThrows(fn()=>$confirm($p),'SYNTHETIC_PARTIAL_FAILURE','score operation rolls back partially applied candidate writes');$db->arm(0);bulkCheck($before===$hash(),'failed score batch restores all identity/member/audit state');$confirm($p);
    foreach(['viewer','analyst'] as $role)bulkThrows(fn()=>$score->preview($users[$role]),'ADMIN_REVIEW_REQUIRED',$role.' cannot preview score confirmations');
}
function runBulkScoreHttpCases(PDO $db,callable $q,callable $reset,callable $pair,callable $hash,callable $http,string $cookie,array $users):void
{
    $reset();$pair();$before=$hash();[$code,$html]=$http('/admin/bulk-matches.php?mode=score',$cookie);bulkCheck($code===200&&str_contains($html,'Bulk Confirm Matches Above 50%')&&str_contains($html,'Candidates with stored score above 0.50')&&$before===$hash(),'authenticated score preview is GET-only and separates score and safety counts');
    preg_match('/name="csrf" value="([a-f0-9]+)"/',$html,$csrf);preg_match('/name="operation_id" value="([a-f0-9]+)"/',$html,$op);
    $post=['csrf'=>$csrf[1],'policy'=>BulkExactMatchService::SCORE,'bulk_action'=>'confirm','operation_id'=>$op[1],'confirm_count'=>'2','confirm_exact'=>'1'];
    [$code]=$http('/admin/bulk-matches.php',$cookie,array_replace($post,['csrf'=>'invalid']));bulkCheck($code===403,'invalid CSRF rejects score confirmation');
    $missing=$post;unset($missing['csrf']);[$code]=$http('/admin/bulk-matches.php',$cookie,$missing);bulkCheck($code===403,'missing CSRF rejects score confirmation');
    foreach(['viewer','analyst'] as $role){[$code]=$http('/admin/bulk-matches.php?mode=score',dirname($cookie).'/'.$role.'.cookies');bulkCheck($code===403,$role.' cannot access the score policy URL directly');}
    [$code]=$http('/admin/bulk-matches.php',$cookie,array_replace($post,['policy'=>BulkExactMatchService::EXACT]));bulkCheck($code===409&&$before===$hash(),'client cannot switch confirmation policy under an existing preview');
    [$code,$html]=$http('/admin/bulk-matches.php?mode=score',$cookie);preg_match('/name="operation_id" value="([a-f0-9]+)"/',$html,$op);$post['operation_id']=$op[1];
    bulkCheck(str_contains($html,'data-confirm-bulk="Confirm 2 candidate decisions? BMA people to create: 1; memberships to create: 0')&&str_contains($html,'/assets/js/bulk-match-review.js'),'score confirmation dialog states exact people/member/association counts');
    [$code]=$http('/admin/bulk-matches.php',$cookie,$post);bulkCheck($code===303&&(int)$q("SELECT COUNT(*) FROM identity_match_candidates WHERE match_status='confirmed'")->fetchColumn()===2,'explicit score-policy CSRF POST succeeds only in the disposable database');
    $before=$hash();[$code]=$http('/admin/bulk-matches.php',$cookie,$post);bulkCheck($code===303&&$before===$hash(),'repeated score-policy POST replays receipt without writes');
    [$code]=$http('/admin/bulk-matches.php?mode=score');bulkCheck($code===303,'unauthenticated direct score preview access denied');
}
